CREATE TABLE "categories" ("id" text PRIMARY KEY NOT NULL, "slug" text NOT NULL, "name" text NOT NULL, "subtitle" text, "sort_order" integer NOT NULL, "active" boolean DEFAULT true NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "categories_slug_unique" ON "categories" ("slug");
CREATE TABLE "products" ("id" text PRIMARY KEY NOT NULL, "slug" text NOT NULL, "category_id" text NOT NULL REFERENCES "categories"("id"), "name" text NOT NULL, "subtitle" text, "description" text, "image" text, "active" boolean DEFAULT true NOT NULL, "sort_order" integer NOT NULL, "base_price_cents" integer NOT NULL, "from_price" boolean DEFAULT false NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "products_slug_unique" ON "products" ("slug");
CREATE TABLE "product_variants" ("id" text PRIMARY KEY NOT NULL, "product_id" text NOT NULL REFERENCES "products"("id") ON DELETE cascade, "name" text NOT NULL, "price_cents" integer NOT NULL, "sort_order" integer NOT NULL, "active" boolean DEFAULT true NOT NULL);
CREATE TABLE "option_groups" ("id" text PRIMARY KEY NOT NULL, "product_id" text NOT NULL REFERENCES "products"("id") ON DELETE cascade, "label" text NOT NULL, "hint" text, "type" text NOT NULL, "required" boolean DEFAULT false NOT NULL, "min_selectable" integer DEFAULT 0 NOT NULL, "max_selectable" integer, "sort_order" integer NOT NULL);
CREATE TABLE "product_options" ("id" text PRIMARY KEY NOT NULL, "option_group_id" text NOT NULL REFERENCES "option_groups"("id") ON DELETE cascade, "name" text NOT NULL, "price_cents" integer NOT NULL, "active" boolean DEFAULT true NOT NULL, "sort_order" integer NOT NULL);
CREATE TABLE "store_config" ("id" text PRIMARY KEY NOT NULL, "name" text NOT NULL, "city" text NOT NULL, "tagline" text NOT NULL, "delivery_mode" text NOT NULL, "whatsapp_number" text NOT NULL, "min_order_cents" integer NOT NULL, "schedule" jsonb NOT NULL, "address" jsonb NOT NULL, "payment_methods" jsonb NOT NULL, "delivery_note" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
